#include <iostream>
#include <vector>
#include <string>
#include <utility>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> edges(m, vector<long long>(3));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 3; j++) {
            cin >> edges[i][j];
        }
    }

    vector<vector<pair<int, int>>> adj(n + 1);
    for (long long i = 0; i < m; i++) {
        int u = (int)edges[i][0], v = (int)edges[i][1], w = (int)edges[i][2];
        adj[u].push_back(make_pair(v, w));
        adj[v].push_back(make_pair(u, w));
    }
    vector<int> d(n + 1, -1);
    d[1] = 0;
    vector<int> queue(1, 1);
    for (size_t head = 0; head < queue.size(); head++) {
        int u = queue[head];
        for (size_t k = 0; k < adj[u].size(); k++) {
            int v = adj[u][k].first, w = adj[u][k].second;
            if (d[v] < 0) {
                d[v] = d[u] ^ w;
                queue.push_back(v);
            }
        }
    }
    vector<int> basis(30, 0);
    for (long long i = 0; i < m; i++) {
        int x = d[edges[i][0]] ^ d[edges[i][1]] ^ (int)edges[i][2];
        for (int b = 29; b >= 0; b--) {
            if (((x >> b) & 1) == 0) continue;
            if (basis[b] == 0) {
                basis[b] = x;
                break;
            }
            x ^= basis[b];
        }
    }
    int res = d[n];
    for (int b = 29; b >= 0; b--) {
        if ((res ^ basis[b]) > res) res ^= basis[b];
    }
    cout << res << "\n";

    return 0;
}

