import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long m = Long.parseLong(next());
        long[][] edges = new long[(int) m][3];
        for (int i = 0; i < edges.length; i++) {
            for (int j = 0; j < edges[i].length; j++) {
                edges[i][j] = Long.parseLong(next());
            }
        }

        int cn = (int) n, cm = (int) m;
        int[] start = new int[cn + 2];
        for (int i = 0; i < cm; i++) {
            start[(int) edges[i][0] + 1]++;
            start[(int) edges[i][1] + 1]++;
        }
        for (int v = 1; v <= cn + 1; v++) start[v] += start[v - 1];
        int[] fill = new int[cn + 2];
        int[] adjTo = new int[2 * cm];
        int[] adjW = new int[2 * cm];
        for (int i = 0; i < cm; i++) {
            int u = (int) edges[i][0], v = (int) edges[i][1], w = (int) edges[i][2];
            adjTo[start[u] + fill[u]] = v;
            adjW[start[u] + fill[u]] = w;
            fill[u]++;
            adjTo[start[v] + fill[v]] = u;
            adjW[start[v] + fill[v]] = w;
            fill[v]++;
        }
        int[] d = new int[cn + 1];
        Arrays.fill(d, -1);
        d[1] = 0;
        int[] queue = new int[cn];
        int head = 0, tail = 0;
        queue[tail++] = 1;
        while (head < tail) {
            int u = queue[head++];
            for (int k = start[u]; k < start[u + 1]; k++) {
                int v = adjTo[k];
                if (d[v] < 0) {
                    d[v] = d[u] ^ adjW[k];
                    queue[tail++] = v;
                }
            }
        }
        int[] basis = new int[30];
        for (int i = 0; i < cm; i++) {
            int x = d[(int) edges[i][0]] ^ d[(int) edges[i][1]] ^ (int) edges[i][2];
            for (int b = 29; b >= 0; b--) {
                if (((x >> b) & 1) == 0) continue;
                if (basis[b] == 0) {
                    basis[b] = x;
                    break;
                }
                x ^= basis[b];
            }
        }
        int res = d[cn];
        for (int b = 29; b >= 0; b--) {
            if ((res ^ basis[b]) > res) res ^= basis[b];
        }
        System.out.println(res);
    }
}
